-- Seventh fixed refund observation; ordinary-role transaction boundary.

CREATE OR REPLACE FUNCTION public.order_refund_observe_v1(p_locator jsonb,p_source text,p_event_hex text,p_observed jsonb,p_dedupe_hash text,p_claim jsonb,p_now jsonb,p_enqueue boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER
SET search_path=pg_catalog,public SET TimeZone='UTC' AS $order_rpc$
DECLARE r public.refunds%ROWTYPE;p public.prepayments%ROWTYPE;o public.orders%ROWTYPE;c public.notification_consents%ROWTYPE;n public.notification_outbox%ROWTYPE;refund_id numeric;payment_id numeric;order_id numeric;observation_id numeric;pg_us numeric;now_at timestamptz;success_at timestamptz;affected bigint;mismatch text;reason text;new_provider text;applied boolean;notification_now timestamptz;notification_user numeric;message jsonb;order_no_text text;
failure_state text;failure_constraint text;
BEGIN
 IF current_user<>'authenticated' OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS DISTINCT FROM '__ORDER_SERVICE_UID__' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ORDER_RUNTIME_FORBIDDEN';END IF;
 BEGIN
IF jsonb_typeof((p_locator-'order_id')) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys((p_locator-'order_id')))<>2 OR jsonb_typeof((p_locator-'order_id')->'refund_id') IS DISTINCT FROM 'string' OR jsonb_typeof((p_locator-'order_id')->'prepayment_id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF (SELECT count(*) FROM jsonb_object_keys(p_locator))<>3 OR NOT (p_locator ? 'order_id') OR jsonb_typeof(p_locator->'order_id') NOT IN ('string','null') THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF p_locator->>'refund_id' IS NULL OR p_locator->>'refund_id' !~ '^(0|[1-9][0-9]*)$' OR (p_locator->>'refund_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_locator->>'prepayment_id' IS NULL OR p_locator->>'prepayment_id' !~ '^(0|[1-9][0-9]*)$' OR (p_locator->>'prepayment_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_locator->'order_id'<>'null'::jsonb THEN IF p_locator->>'order_id' IS NULL OR p_locator->>'order_id' !~ '^(0|[1-9][0-9]*)$' OR (p_locator->>'order_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
END IF;refund_id:=(p_locator->>'refund_id')::numeric;payment_id:=(p_locator->>'prepayment_id')::numeric;order_id:=(p_locator->>'order_id')::numeric;
SELECT out_trade_no,expected_mchid,expected_amount_cents,currency INTO p.out_trade_no,p.expected_mchid,p.expected_amount_cents,p.currency FROM public.prepayments WHERE id=payment_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;IF p.out_trade_no IS NULL OR p.expected_mchid IS NULL OR p.expected_amount_cents IS NULL OR p.currency IS NULL OR p.expected_amount_cents NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF order_id IS NOT NULL THEN SELECT id,user_id,state,transaction_id,order_no,pickup_at,payable_cents,refunding_at INTO o.id,o.user_id,o.state,o.transaction_id,o.order_no,o.pickup_at,o.payable_cents,o.refunding_at FROM public.orders WHERE id=order_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_FOUND');END IF;IF o.id IS NULL OR o.user_id IS NULL OR o.state IS NULL OR o.transaction_id IS NULL OR o.order_no IS NULL OR o.pickup_at IS NULL OR NOT isfinite(o.pickup_at) OR o.payable_cents IS NULL OR o.id NOT BETWEEN 0 AND 18446744073709551615 OR o.user_id NOT BETWEEN 0 AND 18446744073709551615 OR o.payable_cents NOT BETWEEN 0 AND 18446744073709551615 OR (o.refunding_at IS NOT NULL AND NOT isfinite(o.refunding_at)) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;END IF;
SELECT * INTO r FROM public.refunds WHERE id=refund_id FOR UPDATE;IF NOT FOUND OR r.id IS NULL OR r.prepayment_id IS NULL OR r.provider_state IS NULL OR r.materialization_state IS NULL OR r.amount_cents IS NULL OR r.currency IS NULL OR r.created_at IS NULL OR NOT isfinite(r.created_at) OR r.idempotency_key_hash IS NULL OR r.provider_request_json IS NULL OR r.reason_code IS NULL OR r.record_version IS NULL OR r.id NOT BETWEEN 0 AND 18446744073709551615 OR r.prepayment_id NOT BETWEEN 0 AND 18446744073709551615 OR r.order_id NOT BETWEEN 0 AND 18446744073709551615 OR r.amount_cents NOT BETWEEN 0 AND 18446744073709551615 OR r.requested_by_user_id NOT BETWEEN 0 AND 18446744073709551615 OR r.requested_by_account_id NOT BETWEEN 0 AND 18446744073709551615 OR r.record_version NOT BETWEEN 0 AND 18446744073709551615 OR (r.lease_expires_at IS NOT NULL AND NOT isfinite(r.lease_expires_at)) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;order_id:=r.order_id;
IF jsonb_typeof(p_now) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_now))<>4 OR jsonb_typeof(p_now->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof(p_now->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof(p_now->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_now->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_now->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR (p_now->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR p_now->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR (p_now->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_claim IS NOT NULL THEN IF jsonb_typeof(p_claim) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_claim))<>3 OR jsonb_typeof(p_claim->'refund_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_claim->'owner_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(p_claim->'version') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_claim->>'refund_id' IS NULL OR p_claim->>'refund_id' !~ '^(0|[1-9][0-9]*)$' OR (p_claim->>'refund_id')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_claim->>'version' IS NULL OR p_claim->>'version' !~ '^(0|[1-9][0-9]*)$' OR (p_claim->>'version')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_claim->>'owner_hex' !~ '^[0-9a-f]{32}$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF (p_claim->>'refund_id')::numeric<>refund_id OR r.lease_kind IS DISTINCT FROM 'QUERY' OR r.lease_owner IS DISTINCT FROM decode(p_claim->>'owner_hex','hex') OR r.record_version<>(p_claim->>'version')::numeric OR r.lease_expires_at IS NULL OR ((p_now->>'epoch_seconds')::numeric*1000000000+(p_now->>'nanosecond')::numeric)>=extract(epoch FROM r.lease_expires_at)*1000000000 THEN RETURN jsonb_build_object('outcome','STALE_QUERY_LEASE');END IF;END IF;
IF jsonb_typeof(p_observed) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_observed))<>10 OR jsonb_typeof(p_observed->'merchant_id_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'out_trade_no_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'transaction_id_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'out_refund_no_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'refund_id_hex') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'state') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'amount_cents') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'total_cents') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'currency') IS DISTINCT FROM 'string' OR jsonb_typeof(p_observed->'success_time') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'merchant_id_hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'out_trade_no_hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'transaction_id_hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'out_refund_no_hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'refund_id_hex' !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'amount_cents' !~ '^(0|[1-9][0-9]*)$' OR (p_observed->>'amount_cents')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF p_observed->>'total_cents' !~ '^(0|[1-9][0-9]*)$' OR (p_observed->>'total_cents')::numeric>18446744073709551615 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF jsonb_typeof((p_observed->'success_time')) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys((p_observed->'success_time')))<>4 OR jsonb_typeof((p_observed->'success_time')->'epoch_seconds') IS DISTINCT FROM 'string' OR jsonb_typeof((p_observed->'success_time')->'nanosecond') IS DISTINCT FROM 'number' OR jsonb_typeof((p_observed->'success_time')->'zero') IS DISTINCT FROM 'boolean' OR jsonb_typeof((p_observed->'success_time')->'canonical') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
IF (p_observed->'success_time')->>'epoch_seconds' !~ '^(0|-?[1-9][0-9]*)$' OR ((p_observed->'success_time')->>'epoch_seconds')::numeric NOT BETWEEN -9223372036854775808 AND 9223372036854775807 OR (p_observed->'success_time')->>'nanosecond' !~ '^(0|[1-9][0-9]*)$' OR ((p_observed->'success_time')->>'nanosecond')::numeric NOT BETWEEN 0 AND 999999999 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
mismatch:=CASE WHEN p.expected_mchid=''::bytea OR p.expected_mchid<>decode(p_observed->>'merchant_id_hex','hex') THEN 'MERCHANT_MISMATCH' WHEN p.out_trade_no=''::bytea OR p.out_trade_no<>decode(p_observed->>'out_trade_no_hex','hex') THEN 'OUT_TRADE_NO_MISMATCH' WHEN order_id IS NOT NULL AND o.transaction_id<>''::bytea AND o.transaction_id<>decode(p_observed->>'transaction_id_hex','hex') THEN 'TRANSACTION_ID_MISMATCH' WHEN p_observed->>'out_refund_no_hex'='' THEN 'OUT_REFUND_NO_MISMATCH' WHEN p_observed->>'refund_id_hex'='' THEN 'REFUND_ID_MISSING' WHEN r.amount_cents=0 OR r.amount_cents<>(p_observed->>'amount_cents')::numeric OR r.amount_cents<>(p_observed->>'total_cents')::numeric THEN 'AMOUNT_MISMATCH' WHEN r.currency<>'CNY' OR r.currency<>p_observed->>'currency' THEN 'CURRENCY_MISMATCH' WHEN p_observed->>'state'='SUCCESS' AND (p_observed->'success_time'->>'zero')::boolean THEN 'SUCCESS_TIME_MISSING' WHEN p_observed->>'state' NOT IN ('PROCESSING','SUCCESS','CLOSED') THEN 'PROVIDER_STATE_INVALID' ELSE NULL END;
IF mismatch IS NULL AND r.provider_refund_id IS NOT NULL AND r.provider_refund_id<>decode(p_observed->>'refund_id_hex','hex') THEN mismatch:='REFUND_ID_MISMATCH';END IF;IF mismatch IS NULL AND order_id IS NOT NULL AND p_observed->>'state'='SUCCESS' AND ((p_observed->'success_time'->>'zero')::boolean OR (((p_observed->'success_time')->>'epoch_seconds')::numeric*1000000000+((p_observed->'success_time')->>'nanosecond')::numeric)<extract(epoch FROM coalesce(o.refunding_at,'0001-01-01T00:00:00Z'::timestamptz))*1000000000) THEN mismatch:='SUCCESS_TIME_INVALID';END IF;reason:=coalesce(mismatch,'PROVIDER_'||(p_observed->>'state'));
IF NOT (p_observed->'success_time'->>'zero')::boolean THEN pg_us:=mod(((p_observed->'success_time')->>'epoch_seconds')::numeric*1000000+div(((p_observed->'success_time')->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN success_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN success_at:='-infinity'::timestamptz;ELSE success_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
END IF;pg_us:=mod((p_now->>'epoch_seconds')::numeric*1000000+div((p_now->>'nanosecond')::numeric,1000)-946684800000000,18446744073709551616);IF pg_us<0 THEN pg_us:=pg_us+18446744073709551616;END IF;IF pg_us>=9223372036854775808 THEN pg_us:=pg_us-18446744073709551616;END IF;
IF pg_us=9223372036854775807 THEN now_at:='infinity'::timestamptz;ELSIF pg_us=-9223372036854775808 THEN now_at:='-infinity'::timestamptz;ELSE now_at:='2000-01-01T00:00:00Z'::timestamptz+(div(pg_us,86400000000)::text||' days '||mod(pg_us,86400000000)::text||' microseconds')::interval;END IF;
IF p_dedupe_hash !~ '^[0-9a-f]{64}$' OR p_event_hex !~ '^([0-9a-f]{2})*$' THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;INSERT INTO public.refund_observations(refund_id,dedupe_key,source,provider_event_id,out_refund_no,provider_refund_id,provider_state,validation,mismatch_code,success_time,received_at,apply_state,apply_reason_code,applied_at,record_version) VALUES(refund_id,decode(p_dedupe_hash,'hex'),p_source,CASE WHEN p_event_hex='' THEN NULL ELSE decode(p_event_hex,'hex') END,decode(p_observed->>'out_refund_no_hex','hex'),decode(p_observed->>'refund_id_hex','hex'),p_observed->>'state',CASE WHEN mismatch IS NULL THEN 'MATCH' ELSE 'MISMATCH' END,mismatch,success_at,now_at,'NEW',NULL,NULL,1) ON CONFLICT ON CONSTRAINT uq_refund_observations_dedupe DO NOTHING;GET DIAGNOSTICS affected=ROW_COUNT;
IF affected=0 THEN IF p_claim IS NOT NULL THEN UPDATE public.refunds SET lease_kind=NULL,lease_owner=NULL,lease_expires_at=NULL,next_query_at=NULL,record_version=record_version+1,updated_at=now_at WHERE id=refund_id;END IF;RETURN jsonb_build_object('outcome','OBSERVED','applied',r.materialization_state='APPLIED');END IF;SELECT id INTO observation_id FROM public.refund_observations WHERE dedupe_key=decode(p_dedupe_hash,'hex');IF NOT FOUND OR observation_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;
new_provider:=CASE WHEN r.provider_state='SUCCESS' OR p_observed->>'state'='SUCCESS' THEN 'SUCCESS' WHEN r.provider_state='CLOSED' OR p_observed->>'state'='CLOSED' THEN 'CLOSED' WHEN p_observed->>'state'='PROCESSING' THEN 'PROCESSING' ELSE r.provider_state END;applied:=mismatch IS NULL AND p_observed->>'state'='SUCCESS' AND (order_id IS NULL OR o.state IN ('REFUNDING','REFUNDED'));IF applied THEN
IF order_id IS NOT NULL AND o.state<>'REFUNDED' THEN UPDATE public.orders SET state='REFUNDED',refunded_at=success_at,record_version=record_version+1,updated_at=now_at WHERE id=o.id AND state='REFUNDING';END IF;IF order_id IS NULL THEN UPDATE public.prepayments SET materialization_state='REFUNDED_WITHOUT_ORDER',pending_reason_code=NULL,materialized_at=now_at,record_version=record_version+1,updated_at=now_at WHERE id=payment_id;END IF;UPDATE public.refunds SET provider_state=new_provider,provider_refund_id=decode(p_observed->>'refund_id_hex','hex'),materialization_state='APPLIED',pending_reason_code=NULL,materialized_at=now_at,lease_kind=NULL,lease_owner=NULL,lease_expires_at=NULL,next_query_at=NULL,record_version=record_version+1,updated_at=now_at WHERE id=refund_id;UPDATE public.refund_observations SET apply_state='APPLIED',apply_reason_code=NULL,applied_at=now_at,record_version=record_version+1 WHERE id=observation_id;
IF order_id IS NOT NULL AND p_enqueue IS NULL THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;IF p_enqueue AND order_id IS NOT NULL THEN order_no_text:=convert_from(o.order_no,'UTF8');IF o.id=0 OR o.user_id=0 OR (p_now->>'zero')::boolean OR octet_length(o.order_no) NOT BETWEEN 1 AND 64 OR btrim(order_no_text,chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288))<>order_no_text THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;notification_now:=clock_timestamp();SELECT user_id INTO notification_user FROM public.orders WHERE id=o.id FOR UPDATE;IF NOT FOUND OR notification_user<>o.user_id THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;SELECT id,user_id,template_config_version,consumed_at INTO c.id,c.user_id,c.template_config_version,c.consumed_at FROM public.notification_consents nc WHERE nc.order_id=o.id AND nc.kind='REFUND_RESULT' AND decision='ACCEPTED' ORDER BY grant_sequence LIMIT 1 FOR UPDATE;IF FOUND THEN IF c.user_id<>o.user_id OR c.id IS NULL OR c.template_config_version IS NULL OR c.id NOT BETWEEN 0 AND 18446744073709551615 OR c.user_id NOT BETWEEN 0 AND 18446744073709551615 OR c.template_config_version NOT BETWEEN 0 AND 18446744073709551615 OR (c.consumed_at IS NOT NULL AND NOT isfinite(c.consumed_at)) THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;message:=jsonb_build_object('order_number',order_no_text,'refund_result','REFUNDED');SELECT consent_id,recipient_user_id,template_config_version,immutable_message_json INTO n.consent_id,n.recipient_user_id,n.template_config_version,n.immutable_message_json FROM public.notification_outbox nox WHERE nox.order_id=o.id AND nox.kind='REFUND_RESULT' FOR UPDATE;IF FOUND THEN IF n.consent_id IS DISTINCT FROM c.id OR n.recipient_user_id IS DISTINCT FROM o.user_id OR n.template_config_version IS DISTINCT FROM c.template_config_version OR n.immutable_message_json IS DISTINCT FROM message THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;ELSE IF c.consumed_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;INSERT INTO public.notification_outbox(order_id,consent_id,kind,recipient_user_id,immutable_message_json,template_config_version,state,attempt_count,next_attempt_at,lease_owner,lease_expires_at,record_version,provider_message_id,last_error_code,created_at,sent_at) VALUES(o.id,c.id,'REFUND_RESULT',o.user_id,message,c.template_config_version,'PENDING',0,now_at,NULL,NULL,1,NULL,NULL,notification_now,NULL);UPDATE public.notification_consents SET consumed_at=notification_now WHERE id=c.id AND consumed_at IS NULL;GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION USING ERRCODE='P1000',MESSAGE='ORDER_REFUND_UNAVAILABLE';END IF;END IF;END IF;END IF;reason:='REFUND_CONFIRMED';
ELSE IF p_observed->>'state'='PROCESSING' AND mismatch IS NULL THEN reason:='PROVIDER_PROCESSING';END IF;UPDATE public.refunds SET provider_state=new_provider,provider_refund_id=decode(p_observed->>'refund_id_hex','hex'),materialization_state=CASE WHEN materialization_state='APPLIED' THEN 'APPLIED' WHEN reason='PROVIDER_PROCESSING' THEN materialization_state ELSE 'PENDING_MANUAL' END,pending_reason_code=CASE WHEN materialization_state='APPLIED' THEN NULL WHEN reason='PROVIDER_PROCESSING' THEN pending_reason_code ELSE reason END,lease_kind=NULL,lease_owner=NULL,lease_expires_at=NULL,next_query_at=NULL,record_version=record_version+1,updated_at=now_at WHERE id=refund_id;UPDATE public.refund_observations SET apply_state='DEFERRED',apply_reason_code=reason,record_version=record_version+1 WHERE id=observation_id;END IF;
INSERT INTO public.action_audits(entry_kind,actor_kind,actor_scope_hash,actor_user_id,actor_account_id,action,target_type,target_id,operation_key_hash,result,reason_code,before_state_json,after_state_json,occurred_at) VALUES('SYSTEM_EVIDENCE','PROVIDER',sha256(convert_to('PROVIDER:REFUND','UTF8')),NULL,NULL,'refund.observe','REFUND',refund_id,NULL,CASE WHEN applied THEN 'SUCCEEDED' ELSE 'REJECTED' END,reason,jsonb_build_object('observation',p_observed->>'state'),jsonb_build_object('apply_state',CASE WHEN applied THEN 'APPLIED' ELSE 'DEFERRED' END),now_at);RETURN jsonb_build_object('outcome','OBSERVED','applied',applied);
 EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure_state=RETURNED_SQLSTATE,failure_constraint=CONSTRAINT_NAME;
 IF failure_state IN ('40P01','40001','55P03') THEN RETURN jsonb_build_object('outcome','SQL_FAILURE','sqlstate',failure_state,'constraint','');END IF;
IF failure_state='23505' AND failure_constraint IN ('uq_refunds_prepayment','uq_refunds_order','uq_refunds_out_refund_no','uq_action_audits_command_receipt') THEN RETURN jsonb_build_object('outcome','SQL_FAILURE','sqlstate',failure_state,'constraint',failure_constraint);END IF;
IF failure_state='P1000' THEN RETURN jsonb_build_object('outcome','UNAVAILABLE');END IF;
RAISE;
 END;
END
$order_rpc$;
